package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"

	"github.com/shopspring/decimal"
)

type OrderRec struct { // 01 ORDER-REC, 15 bytes
	OrId string // PIC X(5) @0 len=5
	OrStat string // PIC X(1) @5 len=1
	OrQty int64 // PIC 9(3) @6 len=3
	OrPrice decimal.Decimal // PIC 9(4)V99 @9 len=6
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string // PIC X len=1 = "N"
var WsTotal decimal.Decimal // PIC 9(8)V99 len=10 = 0
var WsGrand decimal.Decimal // PIC 9(10)V99 len=12 = 0
var WsNewCount int64 // PIC 99 len=2 = 0
var WsShipCount int64 // PIC 99 len=2 = 0
var WsCancelCount int64 // PIC 99 len=2 = 0
var WsInvalid int64 // PIC 99 len=2 = 0
var WsBadQty int64 // PIC 99 len=2 = 0
var WsQtyEd string // PIC ZZ9 len=3
var WsPriceEd string // PIC Z,ZZ9.99 len=8
var WsTotalEd string // PIC ZZ,ZZZ,ZZ9.99 len=13
var WsGrandEd string // PIC Z,ZZZ,ZZZ,ZZ9.99 len=16

var OrderRecData OrderRec
var orderLines []string
var orderIdx int

func init() {
	WsEofFlag = "N"
	WsTotal = decimal.NewFromInt(0)
	WsGrand = decimal.NewFromInt(0)
	WsNewCount = 0
	WsShipCount = 0
	WsCancelCount = 0
	WsInvalid = 0
	WsBadQty = 0
	WsQtyEd = ""
	WsPriceEd = ""
	WsTotalEd = ""
	WsGrandEd = ""
}

func isInputDone() bool {
	return WsEofFlag == "Y"
}

func pow10(n int) decimal.Decimal {
	return decimal.NewFromInt(1).Shift(int32(n))
}

func fitPic9V99(d decimal.Decimal, intDigits int, scale int) decimal.Decimal {
	t := d.Truncate(int32(scale))
	scaled := t.Shift(int32(scale))
	modulus := pow10(intDigits + scale)
	moded := scaled.Mod(modulus)
	return moded.Shift(int32(-scale))
}

func formatNumericEdited(val decimal.Decimal, picture string) string {
	dotIdx := strings.Index(picture, ".")
	var intPic, fracPic string
	if dotIdx >= 0 {
		intPic = picture[:dotIdx]
		fracPic = picture[dotIdx+1:]
	} else {
		intPic = picture
		fracPic = ""
	}
	intDigits := 0
	for _, ch := range intPic {
		if ch == 'Z' || ch == '9' {
			intDigits++
		}
	}
	decScale := 0
	for _, ch := range fracPic {
		if ch == 'Z' || ch == '9' {
			decScale++
		}
	}
	t := val.Truncate(int32(decScale))
	scaled := t.Shift(int32(decScale))
	absScaled := scaled.Abs()
	modulus := pow10(intDigits + decScale)
	absMod := absScaled.Mod(modulus)
	divisor := pow10(decScale)
	var intPart int64
	var fracPart int64
	if decScale > 0 {
		intPartDec := absMod.Shift(int32(-decScale)).Truncate(0)
		intPart = intPartDec.IntPart()
		fracDec := absMod.Mod(divisor)
		fracPart = fracDec.IntPart()
	} else {
		intPart = absMod.IntPart()
		fracPart = 0
	}
	digitStr := fmt.Sprintf("%0*d", intDigits, intPart)
	if len(digitStr) > intDigits {
		digitStr = digitStr[len(digitStr)-intDigits:]
	}
	var sb strings.Builder
	digitIdx := 0
	stillSuppress := true
	for _, ch := range intPic {
		if ch == 'Z' || ch == '9' {
			dChar := digitStr[digitIdx]
			digitIdx++
			d := dChar - '0'
			if ch == 'Z' && stillSuppress && d == 0 {
				sb.WriteByte(' ')
			} else {
				sb.WriteByte(dChar)
				stillSuppress = false
			}
		} else if ch == ',' {
			if stillSuppress {
				sb.WriteByte(' ')
			} else {
				sb.WriteByte(',')
			}
		} else {
			sb.WriteByte(byte(ch))
		}
	}
	res := sb.String()
	if decScale > 0 {
		fracStr := fmt.Sprintf("%0*d", decScale, fracPart)
		res += "." + fracStr
	}
	return res
}

func formatPic99(v int64) string {
	m := ((v % 100) + 100) % 100
	return fmt.Sprintf("%02d", m)
}

func parsePic9(s string) int64 {
	t := strings.TrimSpace(s)
	if t == "" {
		return 0
	}
	n, err := strconv.ParseInt(t, 10, 64)
	if err != nil {
		return 0
	}
	return n
}

func parsePic9V99(s string) decimal.Decimal {
	t := strings.TrimSpace(s)
	if t == "" {
		return decimal.NewFromInt(0)
	}
	n, err := strconv.ParseInt(t, 10, 64)
	if err != nil {
		return decimal.NewFromInt(0)
	}
	return decimal.New(n, -2)
}

func MainPara() {
	f, err := os.Open("input.dat")
	if err != nil {
		if os.IsNotExist(err) {
			orderLines = nil
		} else {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
	} else {
		scanner := bufio.NewScanner(f)
		orderLines = nil
		for scanner.Scan() {
			line := scanner.Text()
			orderLines = append(orderLines, line)
		}
		if serr := scanner.Err(); serr != nil {
			fmt.Fprintln(os.Stderr, serr)
			f.Close()
			os.Exit(1)
		}
		f.Close()
	}
	orderIdx = 0
	ReadPara()
	for !isInputDone() {
		ProcessPara()
	}
	SummaryPara()
}

func ReadPara() {
	if orderIdx < len(orderLines) {
		line := orderLines[orderIdx]
		orderIdx++
		var rec string
		if len(line) < 15 {
			rec = line + strings.Repeat(" ", 15-len(line))
		} else if len(line) > 15 {
			rec = line[:15]
		} else {
			rec = line
		}
		OrderRecData.OrId = rec[0:5]
		OrderRecData.OrStat = rec[5:6]
		qtyStr := rec[6:9]
		priceStr := rec[9:15]
		OrderRecData.OrQty = parsePic9(qtyStr)
		OrderRecData.OrPrice = parsePic9V99(priceStr)
	} else {
		WsEofFlag = "Y"
	}
}

func ProcessPara() {
	WsTotal = decimal.NewFromInt(0)
	if OrderRecData.OrQty == 0 {
		WsBadQty = (WsBadQty + 1) % 100
		fmt.Printf("%s BAD QTY\n", OrderRecData.OrId)
	} else if OrderRecData.OrStat == "N" {
		qtyDec := decimal.NewFromInt(OrderRecData.OrQty)
		prod := qtyDec.Mul(OrderRecData.OrPrice)
		WsTotal = fitPic9V99(prod.Truncate(2), 8, 2)
		WsNewCount = (WsNewCount + 1) % 100
		ShowPara()
	} else if OrderRecData.OrStat == "S" {
		qtyDec := decimal.NewFromInt(OrderRecData.OrQty)
		prod := qtyDec.Mul(OrderRecData.OrPrice).Mul(decimal.New(105, -2))
		rounded := prod.Round(2)
		WsTotal = fitPic9V99(rounded, 8, 2)
		WsShipCount = (WsShipCount + 1) % 100
		ShowPara()
	} else if OrderRecData.OrStat == "C" {
		WsCancelCount = (WsCancelCount + 1) % 100
		ShowPara()
	} else {
		WsInvalid = (WsInvalid + 1) % 100
		fmt.Printf("%s BAD STATUS %s\n", OrderRecData.OrId, OrderRecData.OrStat)
	}
	sum := WsGrand.Add(WsTotal)
	WsGrand = fitPic9V99(sum.Truncate(2), 10, 2)
	ReadPara()
}

func ShowPara() {
	WsQtyEd = formatNumericEdited(decimal.NewFromInt(OrderRecData.OrQty), "ZZ9")
	WsPriceEd = formatNumericEdited(OrderRecData.OrPrice, "Z,ZZ9.99")
	WsTotalEd = formatNumericEdited(WsTotal, "ZZ,ZZZ,ZZ9.99")
	fmt.Printf("%s %s %s %s %s\n", OrderRecData.OrId, OrderRecData.OrStat, WsQtyEd, WsPriceEd, WsTotalEd)
}

func SummaryPara() {
	WsGrandEd = formatNumericEdited(WsGrand, "Z,ZZZ,ZZZ,ZZ9.99")
	fmt.Printf("NEW: %s SHIPPED: %s CANCELLED: %s\n", formatPic99(WsNewCount), formatPic99(WsShipCount), formatPic99(WsCancelCount))
	fmt.Printf("INVALID: %s BAD QTY: %s\n", formatPic99(WsInvalid), formatPic99(WsBadQty))
	fmt.Printf("GRAND TOTAL: %s\n", WsGrandEd)
}

func main() {
	MainPara()
}
